INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('0d4d6c31-2b10-5fe0-a097-7eb05292662f', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 20, 20, 'The rest of mankind, who were not killed with these plagues, didn''t repent of the works of their hands, that they wouldn''t worship demons, and the idols of gold, and of silver, and of brass, and of stone, and of wood; which can neither see, nor hear, nor walk.'),
  ('47aa408e-fe4c-5c01-a5ce-0d58e8faef6f', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 21, 21, 'They didn''t repent of their murders, nor of their sorceries, nor of their sexual immorality, nor of their thefts.'),
  ('fc5535f1-5b08-5ab0-aa31-db5fb12788b3', 'de2c76d2-0511-5c9a-abfe-0882cbef25a3', NULL, 1, 1, 'I saw a mighty angel coming down out of the sky, clothed with a cloud. A rainbow was on his head. His face was like the sun, and his feet like pillars of fire.'),
  ('63d79117-1504-5443-ad21-c1631ff4ca2e', 'de2c76d2-0511-5c9a-abfe-0882cbef25a3', NULL, 2, 2, 'He had in his hand a little open book. He set his right foot on the sea, and his left on the land.'),
  ('c290793d-426a-52ba-ac99-73abb6f7f34f', 'de2c76d2-0511-5c9a-abfe-0882cbef25a3', NULL, 3, 3, 'He cried with a loud voice, as a lion roars. When he cried, the seven thunders uttered their voices.'),
  ('ff00d5aa-7a1b-525c-a91a-ae5701560ff3', 'de2c76d2-0511-5c9a-abfe-0882cbef25a3', NULL, 4, 4, 'When the seven thunders sounded, I was about to write; but I heard a voice from the sky saying, "Seal up the things which the seven thunders said, and don''t write them."'),
  ('0a836a5a-0f53-5a7d-adfb-b5f534ca5123', 'de2c76d2-0511-5c9a-abfe-0882cbef25a3', NULL, 5, 5, 'The angel who I saw standing on the sea and on the land lifted up his right hand to the sky,'),
  ('19d572f6-3949-5a28-aa16-345b4481570d', 'de2c76d2-0511-5c9a-abfe-0882cbef25a3', NULL, 6, 6, 'and swore by him who lives forever and ever, who created heaven and the things that are in it, the earth and the things that are in it, and the sea and the things that are in it, that there will no longer be delay,'),
  ('abee963f-c9d9-5eeb-a253-588c48a9c27c', 'de2c76d2-0511-5c9a-abfe-0882cbef25a3', NULL, 7, 7, 'but in the days of the voice of the seventh angel, when he is about to sound, then the mystery of God is finished, as he declared to his servants, the prophets.'),
  ('618514a2-5838-58be-a0ad-ae24b94a01c0', 'de2c76d2-0511-5c9a-abfe-0882cbef25a3', NULL, 8, 8, 'The voice which I heard from heaven, again speaking with me, said, "Go, take the book which is open in the hand of the angel who stands on the sea and on the land."'),
  ('06923d40-3600-593f-ac8d-5bca373ef899', 'de2c76d2-0511-5c9a-abfe-0882cbef25a3', NULL, 9, 9, 'I went to the angel, telling him to give me the little book. He said to me, "Take it, and eat it up. It will make your stomach bitter, but in your mouth it will be as sweet as honey."'),
  ('75390964-883d-5106-a4ee-431f56d27a09', 'de2c76d2-0511-5c9a-abfe-0882cbef25a3', NULL, 10, 10, 'I took the little book out of the angel''s hand, and ate it up. It was as sweet as honey in my mouth. When I had eaten it, my stomach was made bitter.'),
  ('31074357-5e68-5c0b-a3c9-6239ee724ba7', 'de2c76d2-0511-5c9a-abfe-0882cbef25a3', NULL, 11, 11, 'They told me, "You must prophesy again over many peoples, nations, languages, and kings."'),
  ('7b45a3ca-b7ad-5665-a34f-95639d8e4859', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 1, 1, 'A reed like a rod was given to me. Someone said, "Rise, and measure God''s temple, and the altar, and those who worship in it.'),
  ('dca50397-5bdf-5eed-a9a9-fec9b8262bfc', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 2, 2, 'Leave out the court which is outside of the temple, and don''t measure it, for it has been given to the nations. They will tread the holy city under foot for forty-two months.'),
  ('b822998f-8f1b-561f-a3e8-afac884dd69f', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 3, 3, 'I will give power to my two witnesses, and they will prophesy one thousand two hundred sixty days, clothed in sackcloth."'),
  ('e8a9037d-de27-5447-ae84-a0a92db3a481', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 4, 4, 'These are the two olive trees and the two lampstands, standing before the Lord of the earth.'),
  ('359eb6a9-0771-5522-afa1-a6768d058d45', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 5, 5, 'If anyone desires to harm them, fire proceeds out of their mouth and devours their enemies. If anyone desires to harm them, he must be killed in this way.'),
  ('83ee16e4-72bc-55c6-afad-1d4beb6e629f', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 6, 6, 'These have the power to shut up the sky, that it may not rain during the days of their prophecy. They have power over the waters, to turn them into blood, and to strike the earth with every plague, as often as they desire.'),
  ('cd5010e5-4b2c-5df0-a720-6d576c11a703', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 7, 7, 'When they have finished their testimony, the beast that comes up out of the abyss will make war with them, and overcome them, and kill them.'),
  ('3e07dabf-570f-5919-aaf1-ae8899a34835', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 8, 8, 'Their dead bodies will be in the street of the great city, which spiritually is called Sodom and Egypt, where also their Lord was crucified.'),
  ('192bed38-ba80-51de-a5e3-74ad8a719600', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 9, 9, 'From among the peoples, tribes, languages, and nations people will look at their dead bodies for three and a half days, and will not allow their dead bodies to be laid in a tomb.'),
  ('ce902b5b-7775-57ae-a8de-e1202d280ff0', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 10, 10, 'Those who dwell on the earth rejoice over them, and they will be glad. They will give gifts to one another, because these two prophets tormented those who dwell on the earth.'),
  ('19094dd3-b7af-5e6d-a312-5b7f1ff1be0b', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 11, 11, 'After the three and a half days, the breath of life from God entered into them, and they stood on their feet. Great fear fell on those who saw them.'),
  ('555cb652-1386-5e77-afb0-3b45fa89c904', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 12, 12, 'I heard a loud voice from heaven saying to them, "Come up here!" They went up into heaven in the cloud, and their enemies saw them.'),
  ('02cb8f3a-bf22-5d47-ad22-21e538e0bb84', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 13, 13, 'In that day there was a great earthquake, and a tenth of the city fell. Seven thousand people were killed in the earthquake, and the rest were terrified, and gave glory to the God of heaven.'),
  ('2a85793e-a1d5-5c03-a706-2861f14834ca', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 14, 14, 'The second woe is past. Behold, the third woe comes quickly.'),
  ('bb8750dc-5352-514b-acd6-9954692a1942', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 15, 15, 'The seventh angel sounded, and great voices in heaven followed, saying, "The kingdom of the world has become the Kingdom of our Lord, and of his Christ. He will reign forever and ever!"'),
  ('2d0cfcdb-0b5b-5566-a6fc-52c5886ec1f6', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 16, 16, 'The twenty-four elders, who sit on their thrones before God''s throne, fell on their faces and worshiped God,'),
  ('0d458cea-e5d5-5eb4-ac62-fb8bbbb63c00', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 17, 17, 'saying: "We give you thanks, Lord God, the Almighty, the one who is and who was; because you have taken your great power, and reigned.'),
  ('e89ab280-7671-50e8-a230-1cccc1fdf59b', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 18, 18, 'The nations were angry, and your wrath came, as did the time for the dead to be judged, and to give your bondservants the prophets, their reward, as well as to the saints, and those who fear your name, to the small and the great; and to destroy those who destroy the earth."'),
  ('0a60b03c-18ef-51a4-aab9-768cea68b216', '8b8163f8-7c30-5194-a6c4-b44e04305580', NULL, 19, 19, 'God''s temple that is in heaven was opened, and the ark of the Lord''s covenant was seen in his temple. Lightnings, sounds, thunders, an earthquake, and great hail followed.'),
  ('6d10b5f0-c85a-5df3-ab68-64e778f6165f', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 1, 1, 'A great sign was seen in heaven: a woman clothed with the sun, and the moon under her feet, and on her head a crown of twelve stars.'),
  ('74205b32-704f-568d-aea7-515ef91ed68a', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 2, 2, 'She was with child. She cried out in pain, laboring to give birth.'),
  ('7c2ff8bc-8d62-5f4c-a461-c8a5886cde91', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 3, 3, 'Another sign was seen in heaven. Behold, a great red dragon, having seven heads and ten horns, and on his heads seven crowns.'),
  ('6fe832e1-5515-519d-aaf7-b1b6199fbdef', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 4, 4, 'His tail drew one third of the stars of the sky, and threw them to the earth. The dragon stood before the woman who was about to give birth, so that when she gave birth he might devour her child.'),
  ('0769fc85-ff29-5db2-a04f-68a464d28562', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 5, 5, 'She gave birth to a son, a male child, who is to rule all the nations with a rod of iron. Her child was caught up to God, and to his throne.'),
  ('9089b817-7140-5c43-ad73-15c88e30185d', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 6, 6, 'The woman fled into the wilderness, where she has a place prepared by God, that there they may nourish her one thousand two hundred sixty days.'),
  ('cdb17fee-6fb6-59b0-a7de-f644df3403f1', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 7, 7, 'There was war in the sky. Michael and his angels made war on the dragon. The dragon and his angels made war.'),
  ('6240c629-ac35-5f4a-af84-b3635345db8c', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 8, 8, 'They didn''t prevail, neither was a place found for him any more in heaven.'),
  ('17aa88d7-d11f-548e-a83b-b01d007df582', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 9, 9, 'The great dragon was thrown down, the old serpent, he who is called the devil and Satan, the deceiver of the whole world. He was thrown down to the earth, and his angels were thrown down with him.'),
  ('786379ce-2c2d-58db-a261-816fa165956b', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 10, 10, 'I heard a loud voice in heaven, saying, "Now is come the salvation, the power, and the Kingdom of our God, and the authority of his Christ; for the accuser of our brothers has been thrown down, who accuses them before our God day and night.'),
  ('867e9b9f-1168-5c0b-a231-02f2668a3439', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 11, 11, 'They overcame him because of the Lamb''s blood, and because of the word of their testimony. They didn''t love their life, even to death.'),
  ('998c92f6-464d-5177-a050-14f8e4f049bb', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 12, 12, 'Therefore rejoice, heavens, and you who dwell in them. Woe to the earth and to the sea, because the devil has gone down to you, having great wrath, knowing that he has but a short time."'),
  ('2e979299-8014-5e65-a363-22ac56766190', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 13, 13, 'When the dragon saw that he was thrown down to the earth, he persecuted the woman who gave birth to the male child.'),
  ('be3f173d-1ca1-5533-af16-2c594bfea078', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 14, 14, 'Two wings of the great eagle were given to the woman, that she might fly into the wilderness to her place, so that she might be nourished for a time, and times, and half a time, from the face of the serpent.'),
  ('6a6c96e0-ddc6-518f-a11c-1a3dd4493c64', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 15, 15, 'The serpent spewed water out of his mouth after the woman like a river, that he might cause her to be carried away by the stream.'),
  ('bc383744-cf53-58f0-a05b-a19d5fb0843b', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 16, 16, 'The earth helped the woman, and the earth opened its mouth and swallowed up the river which the dragon spewed out of his mouth.'),
  ('e2b711df-374f-5e68-a9ff-66796b0bb9dd', 'ffcc9871-ab7f-50b6-af13-dc579ccebe98', NULL, 17, 17, 'The dragon grew angry with the woman, and went away to make war with the rest of her seed, who keep God''s commandments and hold Jesus'' testimony.'),
  ('4e86a466-c18c-5bad-aa36-ed9951a19a63', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 1, 1, 'Then I stood on the sand of the sea. I saw a beast coming up out of the sea, having ten horns and seven heads. On his horns were ten crowns, and on his heads, blasphemous names.'),
  ('0d3afb08-9523-5e3b-a0ec-2ee80e457a27', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 2, 2, 'The beast which I saw was like a leopard, and his feet were like those of a bear, and his mouth like the mouth of a lion. The dragon gave him his power, his throne, and great authority.'),
  ('576ef6bd-ee44-539d-a3a6-d656b58f8ed5', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 3, 3, 'One of his heads looked like it had been wounded fatally. His fatal wound was healed, and the whole earth marveled at the beast.'),
  ('06af8d8b-4811-5c27-a08c-c83026e4ce5a', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 4, 4, 'They worshiped the dragon, because he gave his authority to the beast, and they worshiped the beast, saying, "Who is like the beast? Who is able to make war with him?"'),
  ('32342620-d2c3-5946-a96b-cc5fb9f85ff0', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 5, 5, 'A mouth speaking great things and blasphemy was given to him. Authority to make war for forty-two months was given to him.'),
  ('bb903b34-a623-5a15-a208-2ce64e403bcc', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 6, 6, 'He opened his mouth for blasphemy against God, to blaspheme his name, and his dwelling, those who dwell in heaven.'),
  ('ff648996-1b08-50a7-a307-3be1de6cbc90', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 7, 7, 'It was given to him to make war with the saints, and to overcome them. Authority over every tribe, people, language, and nation was given to him.'),
  ('559a0ff5-a502-5a5f-a0c5-855fe3fa057f', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 8, 8, 'All who dwell on the earth will worship him, everyone whose name has not been written from the foundation of the world in the book of life of the Lamb who has been killed.'),
  ('605e1794-0f99-58a3-a5ec-0aa99ff7b9f5', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 9, 9, 'If anyone has an ear, let him hear.'),
  ('6160a63b-9bad-5fdd-abac-cdabfa687a59', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 10, 10, 'If anyone is to go into captivity, he will go into captivity. If anyone is to be killed with the sword, he must be killed. Here is the endurance and the faith of the saints.'),
  ('c4ae6985-d9d6-5ded-ab80-0fc45063c48e', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 11, 11, 'I saw another beast coming up out of the earth. He had two horns like a lamb, and he spoke like a dragon.'),
  ('523ff86f-fb10-53d5-a8a0-5d4b425e80a7', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 12, 12, 'He exercises all the authority of the first beast in his presence. He makes the earth and those who dwell in it to worship the first beast, whose fatal wound was healed.'),
  ('266138ca-f611-554f-a4af-afdeb2e5a07d', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 13, 13, 'He performs great signs, even making fire come down out of the sky to the earth in the sight of people.'),
  ('02804c14-d0f7-5f91-a95c-e950f2762c64', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 14, 14, 'He deceives my own people who dwell on the earth because of the signs he was granted to do in front of the beast; saying to those who dwell on the earth, that they should make an image to the beast who had the sword wound and lived.'),
  ('dfa79ddb-bfe0-5fc5-aefa-acd245179c79', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 15, 15, 'It was given to him to give breath to it, to the image of the beast, that the image of the beast should both speak, and cause as many as wouldn''t worship the image of the beast to be killed.'),
  ('1ad09d77-acb8-54bd-a60d-b62a8008d679', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 16, 16, 'He causes all, the small and the great, the rich and the poor, and the free and the slave, to be given marks on their right hands, or on their foreheads;'),
  ('26a13d97-ad39-5106-abe0-7b1080012702', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 17, 17, 'and that no one would be able to buy or to sell, unless he has that mark, the name of the beast or the number of his name.'),
  ('05fd4c41-8c8a-5a5f-a2dd-10a34fbdf570', '2bb2b902-53ad-5adf-a83a-19e114e11573', NULL, 18, 18, 'Here is wisdom. He who has understanding, let him calculate the number of the beast, for it is the number of a man. His number is six hundred sixty-six.'),
  ('60a2b476-1856-5382-afc0-e4b17354294c', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 1, 1, 'I saw, and behold, the Lamb standing on Mount Zion, and with him a number, one hundred forty-four thousand, having his name, and the name of his Father, written on their foreheads.'),
  ('dd1bf959-5eef-530b-a036-4c1e9d10c3a8', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 2, 2, 'I heard a sound from heaven, like the sound of many waters, and like the sound of a great thunder. The sound which I heard was like that of harpists playing on their harps.'),
  ('571e32f8-df95-568f-a91d-e8ad50bb7f60', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 3, 3, 'They sing a new song before the throne, and before the four living creatures and the elders. No one could learn the song except the one hundred forty-four thousand, those who had been redeemed out of the earth.'),
  ('e6e95a3f-aff5-5b92-a9db-292cdffdfb0a', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 4, 4, 'These are those who were not defiled with women, for they are virgins. These are those who follow the Lamb wherever he goes. These were redeemed by Jesus from among men, the first fruits to God and to the Lamb.'),
  ('0c012781-fb02-59ca-a15f-8aec41f346dd', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 5, 5, 'In their mouth was found no lie, for they are blameless.'),
  ('9802b5ff-5aac-59bf-a643-66ec28f1272b', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 6, 6, 'I saw an angel flying in mid heaven, having an eternal Good News to proclaim to those who dwell on the earth, and to every nation, tribe, language, and people.'),
  ('611d3b57-8b71-59e2-a2f1-eac92c9e5a3d', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 7, 7, 'He said with a loud voice, "Fear the Lord, and give him glory; for the hour of his judgment has come. Worship him who made the heaven, the earth, the sea, and the springs of waters!"'),
  ('874ff624-d2d2-5c4f-a7b6-1ccfabc3f591', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 8, 8, 'Another, a second angel, followed, saying, "Babylon the great has fallen, which has made all the nations to drink of the wine of the wrath of her sexual immorality."'),
  ('630af4b1-f978-57f4-a993-56cc9e6a914a', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 9, 9, 'Another angel, a third, followed them, saying with a great voice, "If anyone worships the beast and his image, and receives a mark on his forehead, or on his hand,'),
  ('444a7b5a-ccef-5f0a-a106-b14bda866081', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 10, 10, 'he also will drink of the wine of the wrath of God, which is prepared unmixed in the cup of his anger. He will be tormented with fire and sulfur in the presence of the holy angels, and in the presence of the Lamb.'),
  ('40c38aee-a4d4-5756-a88e-031cf0413dbe', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 11, 11, 'The smoke of their torment goes up forever and ever. They have no rest day and night, those who worship the beast and his image, and whoever receives the mark of his name.'),
  ('32df53f8-c004-51ab-aca2-e5d4bdb337eb', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 12, 12, 'Here is the patience of the saints, those who keep the commandments of God, and the faith of Jesus."'),
  ('5485da26-7717-5b44-a88c-ed56da78dd21', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 13, 13, 'I heard the voice from heaven saying, "Write, ''Blessed are the dead who die in the Lord from now on.''" "Yes," says the Spirit, "that they may rest from their labors; for their works follow with them."'),
  ('1e637b85-a252-5055-a474-33fc65f08858', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 14, 14, 'I looked, and behold, a white cloud; and on the cloud one sitting like a son of man, having on his head a golden crown, and in his hand a sharp sickle.'),
  ('e3e32fe9-63c3-5c0b-a059-95cb8b1cb4af', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 15, 15, 'Another angel came out from the temple, crying with a loud voice to him who sat on the cloud, "Send forth your sickle, and reap; for the hour to reap has come; for the harvest of the earth is ripe!"'),
  ('6d2cc2a2-ebc3-5aa5-a0ef-d54bad432a84', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 16, 16, 'He who sat on the cloud thrust his sickle on the earth, and the earth was reaped.'),
  ('4d2cb558-ce24-52d1-ae7c-30f6457f4b2c', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 17, 17, 'Another angel came out from the temple which is in heaven. He also had a sharp sickle.'),
  ('3eed173d-4aa5-5d61-a4ac-ffc7263fecf1', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 18, 18, 'Another angel came out from the altar, he who has power over fire, and he called with a great voice to him who had the sharp sickle, saying, "Send forth your sharp sickle, and gather the clusters of the vine of the earth, for the earth''s grapes are fully ripe!"'),
  ('0cdadddf-9971-5718-a3d2-2c07267291af', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 19, 19, 'The angel thrust his sickle into the earth, and gathered the vintage of the earth, and threw it into the great winepress of the wrath of God.'),
  ('503a907f-354b-571b-a553-d14f84d3b9a9', 'f5a6588d-590b-5b1a-aa40-c3b68f25addb', NULL, 20, 20, 'The winepress was trodden outside of the city, and blood came out from the winepress, even to the bridles of the horses, as far as one thousand six hundred stadia.'),
  ('014299b8-364c-5e70-a7a3-08c00dd1dc06', '99748c9f-f5ff-518f-a5f7-7fd94787be6b', NULL, 1, 1, 'I saw another great and marvelous sign in the sky: seven angels having the seven last plagues, for in them God''s wrath is finished.'),
  ('e374b832-ca92-535d-a1d9-7922c56ea7e4', '99748c9f-f5ff-518f-a5f7-7fd94787be6b', NULL, 2, 2, 'I saw something like a sea of glass mixed with fire, and those who overcame the beast, his image, and the number of his name, standing on the sea of glass, having harps of God.'),
  ('164e3606-6524-5527-a071-10fd422814d0', '99748c9f-f5ff-518f-a5f7-7fd94787be6b', NULL, 3, 3, 'They sang the song of Moses, the servant of God, and the song of the Lamb, saying, "Great and marvelous are your works, Lord God, the Almighty! Righteous and true are your ways, you King of the nations.'),
  ('d2404012-7964-5250-a3f0-765eb0bcae75', '99748c9f-f5ff-518f-a5f7-7fd94787be6b', NULL, 4, 4, 'Who wouldn''t fear you, Lord, and glorify your name? For you only are holy. For all the nations will come and worship before you. For your righteous acts have been revealed."'),
  ('ef5f073e-ecb5-584e-a7ed-4eab65acb18a', '99748c9f-f5ff-518f-a5f7-7fd94787be6b', NULL, 5, 5, 'After these things I looked, and the temple of the tabernacle of the testimony in heaven was opened.'),
  ('fbb94eff-533a-50d4-abbd-436bac011048', '99748c9f-f5ff-518f-a5f7-7fd94787be6b', NULL, 6, 6, 'The seven angels who had the seven plagues came out, clothed with pure, bright linen, and wearing golden sashes around their breasts.'),
  ('a959f413-a670-5a34-a8fc-600afe60e16c', '99748c9f-f5ff-518f-a5f7-7fd94787be6b', NULL, 7, 7, 'One of the four living creatures gave to the seven angels seven golden bowls full of the wrath of God, who lives forever and ever.'),
  ('64e7e5bc-ba35-570c-ab29-948242613afb', '99748c9f-f5ff-518f-a5f7-7fd94787be6b', NULL, 8, 8, 'The temple was filled with smoke from the glory of God, and from his power. No one was able to enter into the temple, until the seven plagues of the seven angels would be finished.'),
  ('2e7e75f9-0208-574d-a05c-29195328913f', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 1, 1, 'I heard a loud voice out of the temple, saying to the seven angels, "Go and pour out the seven bowls of the wrath of God on the earth!"'),
  ('afc43cfe-cdb4-52b2-a354-75ad6855e247', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 2, 2, 'The first went, and poured out his bowl into the earth, and it became a harmful and evil sore on the people who had the mark of the beast, and who worshiped his image.'),
  ('dfc8507f-dd3e-56ca-a68e-1a4df888ce96', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 3, 3, 'The second angel poured out his bowl into the sea, and it became blood as of a dead man. Every living thing in the sea died.'),
  ('2400d558-c6b3-5163-acf1-31c2b8dc76f4', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 4, 4, 'The third poured out his bowl into the rivers and springs of water, and they became blood.'),
  ('af58b5b4-88e1-5bd9-ab9f-4a48d60b076e', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 5, 5, 'I heard the angel of the waters saying, "You are righteous, who are and who were, you Holy One, because you have judged these things.'),
  ('294151ea-268b-5b72-a983-b23710d68048', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 6, 6, 'For they poured out the blood of the saints and the prophets, and you have given them blood to drink. They deserve this."'),
  ('69fc08e6-af33-5c1e-a4de-bb57b55fe6c1', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 7, 7, 'I heard the altar saying, "Yes, Lord God, the Almighty, true and righteous are your judgments."'),
  ('4d7b0bab-bc70-5cbb-a926-ce766f7842b3', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 8, 8, 'The fourth poured out his bowl on the sun, and it was given to him to scorch men with fire.'),
  ('507dd520-9b8a-5ceb-a6ef-ca39999eb0cb', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 9, 9, 'People were scorched with great heat, and people blasphemed the name of God who has the power over these plagues. They didn''t repent and give him glory.'),
  ('9800ac16-c224-5312-aeb7-479d719bc383', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 10, 10, 'The fifth poured out his bowl on the throne of the beast, and his kingdom was darkened. They gnawed their tongues because of the pain,'),
  ('4fe7b6ba-eca8-5ccf-ac7b-4cd0cd122ee2', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 11, 11, 'and they blasphemed the God of heaven because of their pains and their sores. They didn''t repent of their works.'),
  ('50302b03-9339-5f0f-adeb-3ecb4ffcda02', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 12, 12, 'The sixth poured out his bowl on the great river, the Euphrates. Its water was dried up, that the way might be prepared for the kings that come from the sunrise.'),
  ('4f37cf19-06d1-5f54-ad2e-94db0a4c5cdc', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 13, 13, 'I saw coming out of the mouth of the dragon, and out of the mouth of the beast, and out of the mouth of the false prophet, three unclean spirits, something like frogs;'),
  ('043f62c9-9b7e-5c45-ab00-1315fffe3c4c', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 14, 14, 'for they are spirits of demons, performing signs; which go forth to the kings of the whole inhabited earth, to gather them together for the war of that great day of God, the Almighty.'),
  ('c74b7d4a-f129-5300-a4e9-99840d3eeba9', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 15, 15, '"Behold, I come like a thief. Blessed is he who watches, and keeps his clothes, so that he doesn''t walk naked, and they see his shame."'),
  ('f34d1fb4-a8ff-55cc-a49f-247461a0f045', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 16, 16, 'He gathered them together into the place which is called in Hebrew, Megiddo.'),
  ('cd71150c-6e49-5dac-a9f3-d5784cfe6fff', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 17, 17, 'The seventh poured out his bowl into the air. A loud voice came forth out of the temple of heaven, from the throne, saying, "It is done!"'),
  ('a57552af-0cf7-5edf-acb2-2c29a2416c7a', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 18, 18, 'There were lightnings, sounds, and thunders; and there was a great earthquake, such as was not since there were men on the earth, so great an earthquake, so mighty.'),
  ('7248afd6-d660-5690-ac47-33bf3189db51', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 19, 19, 'The great city was divided into three parts, and the cities of the nations fell. Babylon the great was remembered in the sight of God, to give to her the cup of the wine of the fierceness of his wrath.'),
  ('ccb25f06-623b-5851-abc3-59963794479b', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 20, 20, 'Every island fled away, and the mountains were not found.'),
  ('e6cce663-252c-5a5d-ac72-47d1c33d08c4', 'd28c870b-0cb4-5013-a015-cb32d1f63804', NULL, 21, 21, 'Great hailstones, about the weight of a talent, came down out of the sky on people. People blasphemed God because of the plague of the hail, for this plague is exceedingly severe.'),
  ('41891f02-41e0-5b65-a0ca-9b3fcdeedc34', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 1, 1, 'One of the seven angels who had the seven bowls came and spoke with me, saying, "Come here. I will show you the judgment of the great prostitute who sits on many waters,'),
  ('8583ea07-52ca-5296-a0d2-cc878144d1ae', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 2, 2, 'with whom the kings of the earth committed sexual immorality, and those who dwell in the earth were made drunken with the wine of her sexual immorality."'),
  ('82cb14b4-8c0e-59a4-ae02-784dae972b90', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 3, 3, 'He carried me away in the Spirit into a wilderness. I saw a woman sitting on a scarlet-colored animal, full of blasphemous names, having seven heads and ten horns.'),
  ('734a3b94-d9fc-5013-ae06-ce529b5da580', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 4, 4, 'The woman was dressed in purple and scarlet, and decked with gold and precious stones and pearls, having in her hand a golden cup full of abominations and the impurities of the sexual immorality of the earth.'),
  ('7f4388d7-e314-5f19-a07b-e29b0fea6946', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 5, 5, 'And on her forehead a name was written, "MYSTERY, BABYLON THE GREAT, THE MOTHER OF THE PROSTITUTES AND OF THE ABOMINATIONS OF THE EARTH."'),
  ('34d6c2d7-5fb4-5452-a965-4cdc42ff5eda', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 6, 6, 'I saw the woman drunken with the blood of the saints, and with the blood of the martyrs of Jesus. When I saw her, I wondered with great amazement.'),
  ('f4e6851a-93a7-5ef4-a106-34ca8dd2ae3f', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 7, 7, 'The angel said to me, "Why do you wonder? I will tell you the mystery of the woman, and of the beast that carries her, which has the seven heads and the ten horns.'),
  ('c13d2223-ded1-5ef2-a1a6-5633e4d6ca9d', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 8, 8, 'The beast that you saw was, and is not; and is about to come up out of the abyss and to go into destruction. Those who dwell on the earth and whose names have not been written in the book of life from the foundation of the world will marvel when they see that the beast was, and is not, and shall be present.'),
  ('0f64cba3-bb7d-5174-adff-06afbaa6d826', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 9, 9, 'Here is the mind that has wisdom. The seven heads are seven mountains, on which the woman sits.'),
  ('a8e9ed67-7ff6-508a-a560-e0342b2b3e54', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 10, 10, 'They are seven kings. Five have fallen, the one is, the other has not yet come. When he comes, he must continue a little while.'),
  ('dc3b7bad-7775-550c-acf4-22384bfd91a6', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 11, 11, 'The beast that was, and is not, is himself also an eighth, and is of the seven; and he goes to destruction.'),
  ('805122fd-d42f-55d6-ab5a-620e1bb68587', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 12, 12, 'The ten horns that you saw are ten kings who have received no kingdom as yet, but they receive authority as kings, with the beast, for one hour.'),
  ('b56e1c00-0e6f-596a-a903-ee4deb7908da', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 13, 13, 'These have one mind, and they give their power and authority to the beast.'),
  ('d8d71012-4552-5b19-a763-14ad007aab23', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 14, 14, 'These will war against the Lamb, and the Lamb will overcome them, for he is Lord of lords, and King of kings. They also will overcome who are with him, called and chosen and faithful."'),
  ('b59cdfb1-4cfa-5340-a4d0-d6ea50a53836', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 15, 15, 'He said to me, "The waters which you saw, where the prostitute sits, are peoples, multitudes, nations, and languages.'),
  ('98c05d0b-150d-5705-afc5-3323277d6948', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 16, 16, 'The ten horns which you saw, and the beast, these will hate the prostitute, and will make her desolate, and will make her naked, and will eat her flesh, and will burn her utterly with fire.'),
  ('575fbdf4-f909-57c3-a7f0-e2e2c42c6b36', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 17, 17, 'For God has put in their hearts to do what he has in mind, and to be of one mind, and to give their kingdom to the beast, until the words of God should be accomplished.'),
  ('a859f44c-f47a-5f9b-a9df-2f45dc61ad66', '001fdc83-d959-5303-a5e5-4687fe98348a', NULL, 18, 18, 'The woman whom you saw is the great city, which reigns over the kings of the earth."'),
  ('aaa900cc-d417-58c8-a6f3-bf5d7e78bd65', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 1, 1, 'After these things, I saw another angel coming down out of the sky, having great authority. The earth was illuminated with his glory.'),
  ('311d9993-6731-501f-a3ba-a12fb73b3cbb', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 2, 2, 'He cried with a mighty voice, saying, "Fallen, fallen is Babylon the great, and she has become a habitation of demons, a prison of every unclean spirit, and a prison of every unclean and hateful bird!'),
  ('b4dee2da-3b80-5956-af6b-2c2b33625c83', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 3, 3, 'For all the nations have drunk of the wine of the wrath of her sexual immorality, the kings of the earth committed sexual immorality with her, and the merchants of the earth grew rich from the abundance of her luxury."'),
  ('95e1e2c0-28ab-54c8-addf-f068819ac2cc', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 4, 4, 'I heard another voice from heaven, saying, "Come out of her, my people, that you have no participation in her sins, and that you don''t receive of her plagues,'),
  ('f27c4fbc-19f7-55c9-a2d2-375491f7b1c9', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 5, 5, 'for her sins have reached to the sky, and God has remembered her iniquities.'),
  ('a1055832-e6dd-50b0-a6a8-525d905337c7', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 6, 6, 'Return to her just as she returned, and repay her double as she did, and according to her works. In the cup which she mixed, mix to her double.'),
  ('1747eecb-7c54-598f-ac91-034e03e181af', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 7, 7, 'However much she glorified herself, and grew wanton, so much give her of torment and mourning. For she says in her heart, ''I sit a queen, and am no widow, and will in no way see mourning.'''),
  ('4be2a5e9-792f-53d5-a4cb-d3d7e31e49e3', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 8, 8, 'Therefore in one day her plagues will come: death, mourning, and famine; and she will be utterly burned with fire; for the Lord God who has judged her is strong.'),
  ('82cd5dda-abc9-517c-a985-49b81ef6629d', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 9, 9, 'The kings of the earth, who committed sexual immorality and lived wantonly with her, will weep and wail over her, when they look at the smoke of her burning,'),
  ('d209a640-defe-589e-a4fa-d96f1048b732', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 10, 10, 'standing far away for the fear of her torment, saying, ''Woe, woe, the great city, Babylon, the strong city! For your judgment has come in one hour.'''),
  ('c13525a4-3175-598f-a9a5-bc734aecb8a6', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 11, 11, 'The merchants of the earth weep and mourn over her, for no one buys their merchandise any more;'),
  ('7e61964f-473e-5ef5-a69b-6a0003eeabc6', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 12, 12, 'merchandise of gold, silver, precious stones, pearls, fine linen, purple, silk, scarlet, all expensive wood, every vessel of ivory, every vessel made of most precious wood, and of brass, and iron, and marble;'),
  ('4ab9f31a-6c83-53f8-af9b-9673a43629e2', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 13, 13, 'and cinnamon, incense, perfume, frankincense, wine, olive oil, fine flour, wheat, sheep, horses, chariots, and people''s bodies and souls.'),
  ('dc59953b-e51a-52b0-a450-0328bfb6f21b', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 14, 14, 'The fruits which your soul lusted after have been lost to you, and all things that were dainty and sumptuous have perished from you, and you will find them no more at all.'),
  ('ec1c40b3-ac83-555f-a64f-6ea52c4b3e0d', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 15, 15, 'The merchants of these things, who were made rich by her, will stand far away for the fear of her torment, weeping and mourning;'),
  ('1d84b83d-03ad-50a6-af51-ae9710bd8f17', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 16, 16, 'saying, ''Woe, woe, the great city, she who was dressed in fine linen, purple, and scarlet, and decked with gold and precious stones and pearls!'),
  ('d628bb02-0b8b-5f3f-a7f8-f78184c50247', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 17, 17, 'For in an hour such great riches are made desolate.'' Every shipmaster, and everyone who sails anywhere, and mariners, and as many as gain their living by sea, stood far away,'),
  ('90968926-efe2-5ac3-afbc-38cc33d41cd6', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 18, 18, 'and cried out as they looked at the smoke of her burning, saying, ''What is like the great city?'''),
  ('049a5a5e-2f9f-56d5-ae36-6839ff94b9a2', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 19, 19, 'They cast dust on their heads, and cried, weeping and mourning, saying, ''Woe, woe, the great city, in which all who had their ships in the sea were made rich by reason of her great wealth!'' For in one hour is she made desolate.'),
  ('749d96ff-5294-5443-ac9f-768d0d29fde8', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 20, 20, '"Rejoice over her, O heaven, you saints, apostles, and prophets; for God has judged your judgment on her."'),
  ('b5d79107-906f-5ba0-a481-707afc7e2612', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 21, 21, 'A mighty angel took up a stone like a great millstone and cast it into the sea, saying, "Thus with violence will Babylon, the great city, be thrown down, and will be found no more at all.'),
  ('e3af6bd8-2e48-59d7-a1ee-d2f388b9dbc9', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 22, 22, 'The voice of harpists, minstrels, flute players, and trumpeters will be heard no more at all in you. No craftsman, of whatever craft, will be found any more at all in you. The sound of a mill will be heard no more at all in you.'),
  ('a91e0bb9-1d4a-55c5-afa8-04abef116aef', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 23, 23, 'The light of a lamp will shine no more at all in you. The voice of the bridegroom and of the bride will be heard no more at all in you; for your merchants were the princes of the earth; for with your sorcery all the nations were deceived.'),
  ('e6d1c64e-ce6a-5913-a084-8d10874b6d1c', 'c975d9cb-ba6e-528d-ae29-c079e94b2e67', NULL, 24, 24, 'In her was found the blood of prophets and of saints, and of all who have been slain on the earth."'),
  ('fa9da7a8-2c3f-53fc-a80d-05cdc3c3846d', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 1, 1, 'After these things I heard something like a loud voice of a great multitude in heaven, saying, "Hallelujah! Salvation, power, and glory belong to our God:'),
  ('4dfd3c73-79b5-5b6f-a709-d2607e977236', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 2, 2, 'for true and righteous are his judgments. For he has judged the great prostitute, who corrupted the earth with her sexual immorality, and he has avenged the blood of his servants at her hand."'),
  ('74aedad1-8466-52be-a0c7-343397f5c1b5', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 3, 3, 'A second said, "Hallelujah! Her smoke goes up forever and ever."'),
  ('0b484c86-4f69-5ded-ab3c-92a343e396b3', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 4, 4, 'The twenty-four elders and the four living creatures fell down and worshiped God who sits on the throne, saying, "Amen! Hallelujah!"'),
  ('bdd8e591-f9a6-5e83-a687-0f392d8c6f33', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 5, 5, 'A voice came forth from the throne, saying, "Give praise to our God, all you his servants, you who fear him, the small and the great!"'),
  ('b5eb5c39-d1bf-5fb1-a23f-5c38882eb49e', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 6, 6, 'I heard something like the voice of a great multitude, and like the voice of many waters, and like the voice of mighty thunders, saying, "Hallelujah! For the Lord our God, the Almighty, reigns!'),
  ('867eda1d-7726-57b9-abea-b582317adc68', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 7, 7, 'Let us rejoice and be exceedingly glad, and let us give the glory to him. For the marriage of the Lamb has come, and his wife has made herself ready."'),
  ('9ebd8744-cd20-534b-ab7a-fd6d6053a4b8', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 8, 8, 'It was given to her that she would array herself in bright, pure, fine linen: for the fine linen is the righteous acts of the saints.'),
  ('7896516b-ba8b-5c27-a033-eae6b20ceb72', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 9, 9, 'He said to me, "Write, ''Blessed are those who are invited to the marriage supper of the Lamb.''" He said to me, "These are true words of God."'),
  ('9bfecfee-c2f5-5908-a71f-97c7464e71f8', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 10, 10, 'I fell down before his feet to worship him. He said to me, "Look! Don''t do it! I am a fellow bondservant with you and with your brothers who hold the testimony of Jesus. Worship God, for the testimony of Jesus is the Spirit of Prophecy."'),
  ('e4c413d1-ba53-573c-ad1e-65b16cca2f12', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 11, 11, 'I saw the heaven opened, and behold, a white horse, and he who sat on it is called Faithful and True. In righteousness he judges and makes war.'),
  ('816d625b-5ea7-521c-af1d-da4ec0e31e3d', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 12, 12, 'His eyes are a flame of fire, and on his head are many crowns. He has names written and a name written which no one knows but he himself.'),
  ('16f5456e-5415-5ffe-a7d0-92c7022c4f4a', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 13, 13, 'He is clothed in a garment sprinkled with blood. His name is called "The Word of God."'),
  ('1cdddf39-f1ec-5cee-ac29-94edfe26ea42', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 14, 14, 'The armies which are in heaven followed him on white horses, clothed in white, pure, fine linen.'),
  ('0328d6e3-ca38-5834-a970-37c8fb13f779', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 15, 15, 'Out of his mouth proceeds a sharp, double-edged sword, that with it he should strike the nations. He will rule them with an iron rod. He treads the winepress of the fierceness of the wrath of God, the Almighty.'),
  ('a73bf121-e3da-5a0f-a89f-8411113b7a6d', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 16, 16, 'He has on his garment and on his thigh a name written, "KING OF KINGS, AND LORD OF LORDS."'),
  ('97ca4306-f83a-5581-a37f-39afb2f97750', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 17, 17, 'I saw an angel standing in the sun. He cried with a loud voice, saying to all the birds that fly in the sky, "Come! Be gathered together to the great supper of God,'),
  ('ddb7d468-cc2b-5c7d-a6a6-cd6b3144bf7b', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 18, 18, 'that you may eat the flesh of kings, the flesh of captains, the flesh of mighty men, and the flesh of horses and of those who sit on them, and the flesh of all men, both free and slave, and small and great."'),
  ('cee8e4ee-df9f-5830-ae46-b8de61efb346', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 19, 19, 'I saw the beast, and the kings of the earth, and their armies, gathered together to make war against him who sat on the horse, and against his army.'),
  ('7c2af35a-4d3b-5685-a62d-abc1041768d3', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 20, 20, 'The beast was taken, and with him the false prophet who worked the signs in his sight, with which he deceived those who had received the mark of the beast and those who worshiped his image. These two were thrown alive into the lake of fire that burns with sulfur.'),
  ('ac860615-cdb5-5ae3-ae92-63a2b62e44f1', 'f5b458af-202f-5550-a622-f8458566eecc', NULL, 21, 21, 'The rest were killed with the sword of him who sat on the horse, the sword which came forth out of his mouth. All the birds were filled with their flesh.'),
  ('b20d0dc7-bf5a-5d7f-a8fb-a14f8925fc70', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 1, 1, 'I saw an angel coming down out of heaven, having the key of the abyss and a great chain in his hand.'),
  ('836794b5-f732-5bea-a247-2a671cdaef7b', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 2, 2, 'He seized the dragon, the old serpent, which is the devil and Satan, who deceives the whole inhabited earth, and bound him for a thousand years,'),
  ('7d2769bf-1c03-5247-af3f-8fa7a7885ba6', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 3, 3, 'and cast him into the abyss, and shut it, and sealed it over him, that he should deceive the nations no more, until the thousand years were finished. After this, he must be freed for a short time.'),
  ('4fd6f953-1a29-5120-a1a4-3b1431406530', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 4, 4, 'I saw thrones, and they sat on them, and judgment was given to them. I saw the souls of those who had been beheaded for the testimony of Jesus, and for the word of God, and such as didn''t worship the beast nor his image, and didn''t receive the mark on their forehead and on their hand. They lived, and reigned with Christ for a thousand years.'),
  ('b6eb531d-a575-52af-a9d3-ca701243735d', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 5, 5, 'The rest of the dead didn''t live until the thousand years were finished. This is the first resurrection.'),
  ('6a8c7f47-8acc-5334-ae09-899df0ff5ab0', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 6, 6, 'Blessed and holy is he who has part in the first resurrection. Over these, the second death has no power, but they will be priests of God and of Christ, and will reign with him one thousand years.'),
  ('190f421e-1ba8-5ab8-a327-008911dbb417', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 7, 7, 'And after the thousand years, Satan will be released from his prison,'),
  ('2425b9e7-c26f-50d2-a2f0-8b69fd648b02', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 8, 8, 'and he will come out to deceive the nations which are in the four corners of the earth, Gog and Magog, to gather them together to the war; the number of whom is as the sand of the sea.'),
  ('a470b84e-9589-5e41-a9a1-77100892c11f', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 9, 9, 'They went up over the breadth of the earth, and surrounded the camp of the saints, and the beloved city. Fire came down out of heaven from God, and devoured them.'),
  ('f76163a2-ce9c-5269-ad80-4ac92c1069d4', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 10, 10, 'The devil who deceived them was thrown into the lake of fire and sulfur, where the beast and the false prophet are also. They will be tormented day and night forever and ever.'),
  ('58339b21-eb67-58a8-a63b-333c0d87c804', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 11, 11, 'I saw a great white throne, and him who sat on it, from whose face the earth and the heaven fled away. There was found no place for them.'),
  ('0db71fdb-e9b9-5938-aa97-d17af229030d', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 12, 12, 'I saw the dead, the great and the small, standing before the throne, and they opened books. Another book was opened, which is the book of life. The dead were judged out of the things which were written in the books, according to their works.'),
  ('24503710-6fd4-579e-a1bf-a692c9016553', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 13, 13, 'The sea gave up the dead who were in it. Death and Hades gave up the dead who were in them. They were judged, each one according to his works.'),
  ('e9cb41d1-c311-5c62-a0ea-f1330e488d0f', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 14, 14, 'Death and Hades were thrown into the lake of fire. This is the second death, the lake of fire.'),
  ('4c21133e-7a82-5346-a8bb-eb0f027ab4e4', '839d2a1e-95fa-5c01-a7cb-697c78b3bb4a', NULL, 15, 15, 'If anyone was not found written in the book of life, he was cast into the lake of fire.'),
  ('4f45aae5-021f-5091-af40-2ce90cb8cc3a', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 1, 1, 'I saw a new heaven and a new earth: for the first heaven and the first earth have passed away, and the sea is no more.'),
  ('aa429d40-06da-550f-a738-557ef2de0c8f', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 2, 2, 'I saw the holy city, New Jerusalem, coming down out of heaven from God, prepared like a bride adorned for her husband.'),
  ('62e5b0db-d29f-5c02-a719-8f868f708059', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 3, 3, 'I heard a loud voice out of heaven saying, "Behold, God''s dwelling is with people, and he will dwell with them, and they will be his people, and God himself will be with them as their God.'),
  ('4420752d-5fa8-551c-a32d-09dd4dab484d', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 4, 4, 'He will wipe away from them every tear from their eyes. Death will be no more; neither will there be mourning, nor crying, nor pain, any more. The first things have passed away."'),
  ('d7a5baa4-85e3-586c-a365-412e93e4a624', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 5, 5, 'He who sits on the throne said, "Behold, I am making all things new." He said, "Write, for these words of God are faithful and true."'),
  ('dcc4686a-4d26-5f62-ad3f-4c5ce9a778f3', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 6, 6, 'He said to me, "It is done! I am the Alpha and the Omega, the Beginning and the End. I will give freely to him who is thirsty from the spring of the water of life.'),
  ('48cdf1ad-cf10-5840-acc6-2009de2aa377', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 7, 7, 'He who overcomes, I will give him these things. I will be his God, and he will be my son.'),
  ('23240578-13bd-5891-acd7-ae6309574966', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 8, 8, 'But for the cowardly, unbelieving, sinners, abominable, murderers, sexually immoral, sorcerers, idolaters, and all liars, their part is in the lake that burns with fire and sulfur, which is the second death."'),
  ('46696986-d7fd-5993-a809-c909d55c753d', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 9, 9, 'One of the seven angels who had the seven bowls, who were loaded with the seven last plagues came, and he spoke with me, saying, "Come here. I will show you the wife, the Lamb''s bride."'),
  ('6cc35fd6-f3d9-569f-a44b-fc6a6f6ad9f8', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 10, 10, 'He carried me away in the Spirit to a great and high mountain, and showed me the holy city, Jerusalem, coming down out of heaven from God,'),
  ('120699e0-49c6-50a8-ad10-b1c3b3ca027e', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 11, 11, 'having the glory of God. Her light was like a most precious stone, as if it was a jasper stone, clear as crystal;'),
  ('2eccd2ec-2608-575a-a708-a2789468a1d5', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 12, 12, 'having a great and high wall; having twelve gates, and at the gates twelve angels; and names written on them, which are the names of the twelve tribes of the children of Israel.'),
  ('be72fe05-3646-5857-ad34-5166618bd4f4', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 13, 13, 'On the east were three gates; and on the north three gates; and on the south three gates; and on the west three gates.'),
  ('a5b79ac2-d626-5b61-a6d9-d8e711df65f9', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 14, 14, 'The wall of the city had twelve foundations, and on them twelve names of the twelve Apostles of the Lamb.'),
  ('9c60ffce-bffd-57e1-ac32-6b53c320a226', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 15, 15, 'He who spoke with me had for a measure, a golden reed, to measure the city, its gates, and its walls.'),
  ('a86ac643-c175-54bc-acc9-9549ce94a28f', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 16, 16, 'The city lies foursquare, and its length is as great as its breadth. He measured the city with the reed, Twelve thousand twelve stadia. Its length, breadth, and height are equal.'),
  ('c323140c-8156-55e0-a794-d69bd228aeef', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 17, 17, 'Its wall is one hundred forty-four cubits, by the measure of a man, that is, of an angel.'),
  ('e000ff4a-62b9-5c53-ae62-258b04867948', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 18, 18, 'The construction of its wall was jasper. The city was pure gold, like pure glass.'),
  ('db2cf449-8e21-5e47-a428-bf7e755679b1', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 19, 19, 'The foundations of the city''s wall were adorned with all kinds of precious stones. The first foundation was jasper; the second, sapphire; the third, chalcedony; the fourth, emerald;'),
  ('a8c3182a-0d7b-5353-ae2e-86f62698b2c1', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 20, 20, 'the fifth, sardonyx; the sixth, sardius; the seventh, chrysolite; the eighth, beryl; the ninth, topaz; the tenth, chrysoprasus; the eleventh, jacinth; and the twelfth, amethyst.'),
  ('8fda42eb-fe62-5ce6-a275-09e516104abe', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 21, 21, 'The twelve gates were twelve pearls. Each one of the gates was made of one pearl. The street of the city was pure gold, like transparent glass.'),
  ('c60b5590-4755-5699-aa54-9b56d3c1e6bb', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 22, 22, 'I saw no temple in it, for the Lord God, the Almighty, and the Lamb, are its temple.'),
  ('ef91cd89-7f32-5838-a8c2-4936f39a213c', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 23, 23, 'The city has no need for the sun, neither of the moon, to shine, for the very glory of God illuminated it, and its lamp is the Lamb.'),
  ('1db4178b-a238-568d-a49b-0fbc1de7af7f', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 24, 24, 'The nations will walk in its light. The kings of the earth bring the glory and honor of the nations into it.'),
  ('51727548-939f-5238-a28c-b4329dbb6a39', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 25, 25, 'Its gates will in no way be shut by day (for there will be no night there),'),
  ('146bda99-ac0e-5bc7-a84f-9377eb830d22', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 26, 26, 'and they shall bring the glory and the honor of the nations into it so that they may enter.'),
  ('411ff873-6a69-5518-ac37-b6855223e61b', 'd9d6fd43-3f48-5700-a86d-c3198be9f973', NULL, 27, 27, 'There will in no way enter into it anything profane, or one who causes an abomination or a lie, but only those who are written in the Lamb''s book of life.'),
  ('4781fcb6-d682-5f45-a5e2-cae79670b90e', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 1, 1, 'He showed me a river of water of life, clear as crystal, proceeding out of the throne of God and of the Lamb,'),
  ('af3df5f5-24c3-5ac9-abdc-4d26b1b4ff75', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 2, 2, 'in the middle of its street. On this side of the river and on that was the tree of life, bearing twelve kinds of fruits, yielding its fruit every month. The leaves of the tree were for the healing of the nations.'),
  ('248f56d2-c480-5b06-a054-4eddd5bbd796', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 3, 3, 'There will be no curse any more. The throne of God and of the Lamb will be in it, and his servants serve him.'),
  ('6541bb9e-f0af-5fab-a90c-e66061b5dfe5', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 4, 4, 'They will see his face, and his name will be on their foreheads.'),
  ('f8c3d5b2-5159-5a71-a2c1-6fbafe540933', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 5, 5, 'There will be no night, and they need no lamp light; for the Lord God will illuminate them. They will reign forever and ever.'),
  ('de54c2a1-4cad-59d7-aeef-291fb288aef8', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 6, 6, 'He said to me, "These words are faithful and true. The Lord God of the spirits of the prophets sent his angel to show to his bondservants the things which must happen soon."'),
  ('71cd35b9-7709-592c-a152-96f520056066', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 7, 7, '"Behold, I come quickly. Blessed is he who keeps the words of the prophecy of this book."'),
  ('0baa3a3f-1def-5150-ae63-e1a2dec6a55f', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 8, 8, 'Now I, John, am the one who heard and saw these things. When I heard and saw, I fell down to worship before the feet of the angel who had shown me these things.'),
  ('8e4c56d9-977c-5990-a5f1-d2c31c802d0c', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 9, 9, 'He said to me, "See you don''t do it! I am a fellow bondservant with you and with your brothers, the prophets, and with those who keep the words of this book. Worship God."'),
  ('c4ebc6de-91be-5925-a6de-d7ae496d1c6c', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 10, 10, 'He said to me, "Don''t seal up the words of the prophecy of this book, for the time is at hand.'),
  ('948b4ca1-8824-59f9-ac54-1ccf35c1949a', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 11, 11, 'He who acts unjustly, let him act unjustly still. He who is filthy, let him be filthy still. He who is righteous, let him do righteousness still. He who is holy, let him be holy still."'),
  ('49fbb397-5d5e-5674-a7f9-b3a92e4eebee', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 12, 12, '"Behold, I come quickly. My reward is with me, to repay to each man according to his work.'),
  ('a78ab9f3-fff3-5b05-a74a-24e33f8812e7', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 13, 13, 'I am the Alpha and the Omega, the First and the Last, the Beginning and the End.'),
  ('502a90bb-f757-5733-a85f-901b3014ebc4', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 14, 14, 'Blessed are those who do his commandments, that they may have the right to the tree of life, and may enter in by the gates into the city.'),
  ('b48ab0c6-9b9f-5e22-a5d2-1e867e000e33', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 15, 15, 'Outside are the dogs, the sorcerers, the sexually immoral, the murderers, the idolaters, and everyone who loves and practices falsehood.'),
  ('6db3d6f2-a84a-556c-a0e0-ad981f98ea65', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 16, 16, 'I, Jesus, have sent my angel to testify these things to you for the assemblies. I am the root and the offspring of David; the Bright and Morning Star."'),
  ('41dd03b9-f98f-5d1b-a53e-20e1b033d4b8', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 17, 17, 'The Spirit and the bride say, "Come!" He who hears, let him say, "Come!" He who is thirsty, let him come. He who desires, let him take the water of life freely.'),
  ('547368ee-fd21-50ce-a255-a3589071db90', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 18, 18, 'I testify to everyone who hears the words of the prophecy of this book, if anyone adds to them, may God add to him the plagues which are written in this book.'),
  ('98be048b-a570-5661-a0f3-1bdd8a9493dd', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 19, 19, 'If anyone takes away from the words of the book of this prophecy, may God take away his part from the tree of life, and out of the holy city, which are written in this book.'),
  ('1c2a8236-d781-55d6-aa0e-a7604482415a', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 20, 20, 'He who testifies these things says, "Yes, I come quickly." Amen! Yes, come, Lord Jesus.'),
  ('2dd777d3-ade1-52fe-a800-f82d34e36fca', 'cbb12a7d-1fc6-5f17-a57e-6033b6d000b1', NULL, 21, 21, 'The grace of the Lord Jesus Christ be with all the saints. Amen.')
